c = Consumer({
    'bootstrap.servers': 'localhost:9092',
    'group.id': 'billing',
    'enable.auto.commit': False,
    'partition.assignment.strategy': 'cooperative-sticky',
})
c.subscribe(['orders'])

while True:
    msg = c.poll(1.0)
    if msg and not msg.error():
        process(msg)          # finish work first
        c.commit(msg, asynchronous=False)  # then commit
